"""Bilingual, static instructions for consuming the catalog with agents and retrieval systems."""
import html

CLONE_COMMAND='git clone https://github.com/reacher-z/Awesome-CUA.git'
RELEASES_URL='https://github.com/reacher-z/Awesome-CUA/releases'


def agent_guide_body(language='en'):
    zh=language=='zh'
    def tr(en,cn):return cn if zh else en
    def command(text):return '<pre class="command-block"><code>'+html.escape(text)+'</code></pre>'
    downloads=[('catalog.jsonl','Complete catalog','完整目录','Every active resource and its full source record.','全部当前资源及完整来源记录。'),
        ('catalog.sqlite','SQLite database','SQLite 数据库','Resources, facets, relations, and full-text search.','资源、标签、关联关系与全文搜索。'),
        ('rag-documents.jsonl','Reviewed retrieval documents','已审阅检索文档','One document per reviewed resource, including citations and provenance.','每项已审阅资源对应一份文档，保留引用与来源。'),
        ('rag-all-records.jsonl','All retrieval documents','全部检索文档','Includes metadata-only entries with their review state intact.','包含论文元数据条目，并保留其待审阅状态。'),
        ('citations.bib','Reviewed paper citations · BibTeX','已审阅论文引用 · BibTeX','Recorded authors, dates, and paper versions.','保留原作者、日期和记录的论文版本。'),
        ('citations.csl.json','Reviewed paper citations · CSL JSON','已审阅论文引用 · CSL JSON','Structured bibliography for reference managers.','用于文献管理工具的结构化书目。'),
        ('rag-manifest.json','RAG export manifest','RAG 导出清单','Counts, SHA-256 fingerprints, and the catalog snapshot fingerprint.','文档数量、SHA-256 指纹与原始目录指纹。')]
    body='<div class="eyebrow">PEOPLE · RAG · AGENTS</div><h1>'+tr('Use the complete catalog with your agent','把完整目录交给你的 Agent')+'</h1>'
    body+='<p class="answer-lead">'+tr('Clone once, search locally, and build retrieval workflows from source-backed records. The full catalog is available without an account or API key.','一行克隆，本地检索，将可追溯的资源记录接入 RAG 和 Agent。完整目录无需账号或 API Key。')+'</p>'
    body+='<p><a href="/AGENTS.md">AGENTS.md</a> · <a href="'+('/agents/' if zh else '/zh/agents/')+'">'+('English' if zh else '中文指南')+'</a></p>'
    body+='<h2>'+tr('1. Clone the data','1. 克隆完整数据')+'</h2>'+command(CLONE_COMMAND+'\ncd Awesome-CUA\ngit rev-parse HEAD')
    body+='<p>'+tr('Read data/catalog.jsonl directly, or use the commands below with Python 3.11+. Search and export use the standard library; no model service or dependency installation is needed. Keep the Git commit as your source snapshot identifier.','直接读取 data/catalog.jsonl，或使用以下 Python 3.11+ 命令。检索和导出只需标准库，无需模型服务或安装依赖。保存 Git commit，便于复核所使用的数据快照。')+'</p>'
    body+='<p><a href="'+RELEASES_URL+'">'+tr('Versioned data snapshots','版本化数据快照')+'</a>'+tr(' provide a complete data ZIP for repeatable ingestion. Verify SHA256SUMS and retain release-manifest.json with the source commit and catalog fingerprint. The bundle includes catalog, RAG, citations and topic subsets; repository CLI commands below require the source clone.','提供可重复使用的完整数据 ZIP。校验 SHA256SUMS，并保留 release-manifest.json 中的源提交与目录指纹。数据包包含目录、RAG、引用和专题子集；以下仓库 CLI 命令需要克隆源代码后运行。')+'</p>'
    body+='<h2>'+tr('2. Ask a focused question','2. 先检索，再深入阅读')+'</h2>'+command('python3 scripts/catalog.py search "grounding" --kind model --status curated --json\npython3 scripts/catalog.py search --kind dataset --environment android --status curated --limit 0 --json\npython3 scripts/catalog.py search --kind paper --status curated --topic reinforcement-learning --limit 0 --json')
    body+='<p>'+tr('Search is literal and uses AND across terms. Use aliases when a query is too narrow; --limit 0 returns all matches. Review status and platform/topic tags describe what the catalog has checked.','检索按关键词进行 AND 匹配。没有结果时可尝试别名；--limit 0 返回全部匹配项。审阅状态、平台和主题标签反映目录已经核实的范围。')+'</p>'
    body+='<h3>'+tr('Retrieve a record by ID','用稳定 ID 读取记录')+'</h3>'+command('python3 scripts/catalog.py get arxiv:2404.07972 --json\npython3 scripts/catalog.py get arxiv:2404.07972 --related --json')
    body+='<p>'+tr('For a field overview, open the ','按方向整理资料时，可先打开')+'<a href="'+('/zh/topics/' if zh else '/topics/')+'">'+tr('topic directory','主题目录')+'</a>'+tr('. Its ','。对应的')+'<a href="/downloads/topics.json">'+tr('JSON manifest','JSON 清单')+'</a>'+tr(' provides exact reviewed member IDs, complete-record subsets, citations and file fingerprints. Pass a downloaded records.jsonl subset to export_rag.py --input to build a focused retrieval corpus. Topics overlap and do not imply dependencies between their members.','提供精确的已审阅资源 ID、完整记录子集、引用和文件指纹。下载的 records.jsonl 可作为 export_rag.py --input 的输入，构建专题检索库。主题可以交叉，同一主题不表示资源间存在依赖关系。')+'</p>'
    body+='<p>'+tr('Exact lookup returns the original record. Related lookup adds reviewed links in both directions, with their source evidence. Unknown and scope-excluded IDs return distinct nonzero exit codes and do not masquerade as active records.','精确查询返回完整原记录。关联查询补充双向的已审阅关系与来源。未知 ID 和已排除 ID 会返回不同的非零退出码，不会被当作当前有效记录。')+'</p>'
    body+='<h3>'+tr('Resolve a recorded former repository name','用已记录的仓库旧名检索')+'</h3>'+command('python3 scripts/catalog.py get github:mnotgod96/appagent --json\npython3 scripts/catalog.py search "https://github.com/mnotgod96/AppAgent" --json')
    body+='<p>'+tr('These commands return the canonical AppAgent record. Use its returned id for joins and retrieval-store updates. The ','以上命令返回 AppAgent 的规范记录，关联查询和检索库更新应使用返回的 id。')+'<a href="/downloads/repository-aliases.json">'+tr('repository identity observations','仓库身份记录')+'</a>'+tr(' bind former and current names to the same numeric GitHub repository ID using paired official API receipts. They are dated identity evidence; they do not create extra resources or change review status. Aliases and their evidence are included in catalog and RAG records.','通过成对的官方 API 收据，将旧名与当前名称绑定到同一个 GitHub 数字仓库 ID。这些是带日期的身份依据，不新增资源，也不改变审阅状态。目录和 RAG 记录均保留别名及其证据。')+'</p>'
    body+='<p>'+tr('Each resource page has a record.json file for direct HTTP retrieval. Scope-excluded records return an explicit excluded decision rather than an active record.','每条资源页面都有 record.json，可直接通过 HTTP 读取。范围排除项会返回明确的 excluded 决定，而非有效资源记录。')+' <a href="/resources/arxiv-2404-07972/record.json">'+tr('Example JSON','JSON 示例')+'</a>.</p>'
    body+='<h2>'+tr('3. Connect a RAG pipeline','3. 接入 RAG')+'</h2>'+command('python3 scripts/export_rag.py --output dist/rag-documents.jsonl\npython3 scripts/export_rag.py --include-metadata --output dist/rag-all-records.jsonl\npython3 scripts/catalog.py build')
    body+='<p>'+tr('Ingest the text field and retain the metadata object. Use id as the stable upsert key. Start with the reviewed export; the full export also includes bibliography entries awaiting relevance review. SQLite is generated at dist/catalog.sqlite.','将 text 字段用于检索，并完整保留 metadata。使用 id 作为稳定的更新键。建议先使用已审阅导出；完整导出还包含相关性待审阅的论文。SQLite 会生成到 dist/catalog.sqlite。')+'</p>'
    body+='<div class="table-scroll"><table class="agent-field-table"><thead><tr><th scope="col">'+tr('Field','字段')+'</th><th scope="col">'+tr('Purpose','用途')+'</th></tr></thead><tbody>'
    fields=[('id / metadata.resource_id','Stable resource identity','稳定的资源标识'),('text','Title, original annotation, context, and source links','标题、原创注释、上下文和来源链接'),('metadata.review_status / metadata.scope','Filter and explain the evidence boundary','用于筛选，并说明证据边界'),('metadata.citation_url / metadata.source_url','Catalog permalink and primary source, including the recorded arXiv version when known','目录固定链接与一手来源；已知时指向记录的 arXiv 版本'),('metadata.evidence / metadata.last_verified_at','Source receipts, fingerprints, and verification dates','来源收据、指纹和核验日期'),('metadata.licenses / metadata.relations','Separate license scopes and reviewed resource relationships','分开的许可范围及已审阅关联'),('metadata.record_sha256','Detect changes to the canonical source-record JSON object','检测规范化后的原始资源 JSON 对象是否发生变化')]
    body+=''.join('<tr><td>'+'<br>'.join('<code>'+html.escape(field).replace('.', '.<wbr>')+'</code>' for field in key.split(' / '))+'</td><td>'+tr(en,cn)+'</td></tr>' for key,en,cn in fields)+'</tbody></table></div>'
    body+='<p>'+tr('Reading catalog.jsonl or record.json directly? Those records use url and details.arxiv_snapshot; the RAG exporter adds the metadata citation URLs and record fingerprint shown above.','直接读取 catalog.jsonl 或 record.json 时，原记录使用 url 和 details.arxiv_snapshot；上表中的 metadata 引用链接与记录指纹由 RAG 导出器生成。')+' <a href="https://github.com/reacher-z/Awesome-CUA/blob/main/docs/query-guide.md#catalog-and-rag-field-mapping">'+tr('Catalog ↔ RAG field mapping','目录与 RAG 字段对照')+'</a>'+tr('.','。')+'</p>'
    body+='<h2>'+tr('4. Export paper citations','4. 导出论文引用')+'</h2>'+command('python3 scripts/export_citations.py --format bibtex --output dist/citations.bib\npython3 scripts/export_citations.py --format csl-json --output dist/citations.csl.json\npython3 scripts/export_citations.py --id arxiv:2404.07972 --format bibtex')
    body+='<p>'+tr('The default exports reviewed papers and surveys. Add --include-metadata for all active bibliography entries. Unknown venues and identifiers are omitted; original publication dates and version-update dates remain separate. Individual paper pages provide their own BibTeX and CSL JSON downloads.','默认导出已审阅论文与综述；添加 --include-metadata 可包含全部当前书目。未知的会议和标识不会被猜测补全，首次提交日期与版本更新时间分别保留。每篇论文页面也提供独立 BibTeX 和 CSL JSON 下载。')+'</p>'
    body+='<h3>'+tr('Select the publication edition','选择正式出版版')+'</h3>'+command('python3 scripts/export_citations.py --edition publication --format bibtex --output dist/publication-citations.bib')
    body+='<p>'+tr('This selects reviewed records with publication metadata. The publication uses its own title, authors, venue and date; the default arXiv citation retains its original preprint version. Publisher-only records use their publication in either mode. Year-only and month-only dates stay partial.','这会选择具有出版信息的已审阅条目。出版版使用自己的题名、作者、会议／期刊和日期；默认 arXiv 引用仍保留原预印本版本。只有出版来源的条目在两种模式下使用同一出版记录。仅知年或月的日期保持原精度。')+'</p><p><a href="/downloads/publication-citations.bib">Publication BibTeX</a> · <a href="/downloads/publication-citations.csl.json">Publication CSL JSON</a> · <a href="/downloads/publications.jsonl">'+tr('Publication observations','出版来源记录')+'</a></p>'
    body+='<h2>'+tr('Ready-to-use downloads','直接下载')+'</h2><p><a href="'+('/zh/data/' if zh else '/data/')+'">'+tr('Open the data hub','打开数据中心')+'</a> · <a href="/downloads/manifest.json">'+tr('Complete download manifest','完整下载清单')+'</a></p><p>'+tr('The manifest lists each main export with its count, unit, scope, byte size and SHA-256. Counts describe overlapping populations; verify the file fingerprint before ingestion and keep catalog_sha256 with your retrieval snapshot.','清单为每个主要导出记录数量、单位、范围、文件大小和 SHA-256。不同导出的内容可能交叉；入库前校验文件指纹，并随检索快照保存 catalog_sha256。')+'</p><ul>'+''.join('<li><a href="/downloads/'+file+'">'+tr(en,cn)+'</a> — '+tr(desc,desc_zh)+'</li>' for file,en,cn,desc,desc_zh in downloads)+'</ul>'
    body+='<h2>'+tr('Keep answers traceable','让回答保留证据')+'</h2><p>'+tr('Curated means AI-assisted editorial review against a primary source. Metadata verified means bibliographic identity was checked; it does not establish relevance or validate findings. Cite the primary resource and catalog permalink, retain dates and recorded versions, and preserve unknown values. Papers, code, datasets, and checkpoints can be related records rather than independent projects.','“已审阅”表示经过 AI 辅助的一手来源编辑核读。“元数据已核验”只确认书目身份，不代表相关性或研究结论已经验证。回答时引用一手来源和目录链接，保留日期、版本与未知字段。论文、代码、数据集和权重可能属于同一项目的不同资源。')+'</p>'
    body+='<p>'+tr('Metadata-only entries may await their first review or remain on hold after source reading. Recorded hold reasons appear in the ','元数据条目可能尚待初审，也可能是在阅读来源后暂缓收录。已记录的暂缓原因见')+'<a href="/downloads/coverage.json">'+tr('coverage ledger','覆盖台账')+'</a>'+tr('. Held records remain outside the reviewed retrieval export.','；暂缓条目仍不进入已审阅检索导出。')+'</p>'
    body+='<p>'+tr('The exports contain catalog metadata and original annotations. Paper full text, model weights, and training examples remain with their publishers. Code, data, weights, and document licenses are separate.','导出内容是目录元数据和原创注释。论文全文、模型权重和训练样本由原发布方提供；代码、数据、权重和文档许可分别记录。')+'</p>'
    body+='<h2>'+tr('Update and reconcile','更新与核对')+'</h2><p>'+tr('Pull a newer Git commit or fetch a new manifest. Compare record_sha256 for changes and reconcile missing IDs against the complete catalog and scope-exclusion ledger. An absent ID may represent a reviewed scope decision; do not leave stale retrieval documents silently active. Discovery is scheduled three times a day, with actual outcomes and gaps recorded on the updates page.','更新到新的 Git commit，或获取新的导出清单。用 record_sha256 比较变更，并对照完整目录和排除台账处理消失的 ID；范围审阅后的排除项不应继续留在检索结果中。发现流程每日计划执行三次，实际执行结果和缺口公开记录在更新页。')+'</p><p><a href="/updates/">'+tr('Scan activity','扫描进展')+'</a> · <a href="/coverage/">'+tr('Coverage ledger','覆盖台账')+'</a> · <a href="/about/">'+tr('Editorial policy','审阅方法')+'</a></p>'
    return body
